package docker

import (
	"path/filepath"
	"sort"
	"strings"
)

func appendPairs(args []string, flag string, values map[string]string) []string {
	keys := make([]string, 0, len(values))
	for key := range values {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	for _, key := range keys {
		args = append(args, flag, key+"="+values[key])
	}
	return args
}

// nativeArguments reconstructs closed typed calls; it never forwards CLI argv.
// The private CID path is generated by the native phase owner, never source input.
func nativeArguments(c Call, cid string) ([]string, error) {
	if !c.Scope.valid() {
		return nil, fail("provider_refused")
	}
	switch c.Kind {
	case "version":
		return []string{"-v"}, nil
	case "engine_version":
		return []string{"version", "--format", "{{.Server.Version}}"}, nil
	case "buildx_version":
		return []string{"buildx", "version"}, nil
	case "image_inspect":
		if c.Reference == "" {
			return nil, fail("provider_refused")
		}
		return []string{"inspect", "--type", "image", c.Reference}, nil
	case "container_inspect", "start":
		if len(c.IDs) != 1 || !hexID.MatchString(c.IDs[0]) {
			return nil, fail("provider_refused")
		}
		if c.Kind == "start" {
			return []string{"start", c.IDs[0]}, nil
		}
		return []string{"inspect", "--type", "container", c.IDs[0]}, nil
	case "pull":
		if _, _, ok := registryRef(c.Reference); !ok {
			return nil, fail("provider_refused")
		}
		return []string{"pull", c.Reference}, nil
	case "discovery", "events":
		args := []string{"ps", "-q", "-a", "--no-trunc"}
		if c.Kind == "events" {
			args = []string{"events", "--format", "{{json .}}", "--filter", "event=start"}
		}
		for _, label := range c.Scope.LabelList() {
			args = append(args, "--filter", "label="+label)
		}
		return args, nil
	case "run":
		r := c.Run
		if r == nil || r.Name != c.Scope.Name() || !strings.HasPrefix(r.ImageID, "sha256:") || !hexID.MatchString(strings.TrimPrefix(r.ImageID, "sha256:")) || !filepath.IsAbs(cid) || filepath.Clean(cid) != cid || filepath.Base(cid) != c.Scope.RuntimeID+".cid" {
			return nil, fail("provider_refused")
		}
		args := []string{"run", "--sig-proxy=false", "-a", "STDOUT", "-a", "STDERR", "--pull", "never", "--cidfile", cid, "--mount", r.Mount}
		args = appendPairs(args, "-l", r.Labels)
		args = appendPairs(args, "-e", r.Env)
		args = append(args, "-u", r.User, "--name", r.Name, "--entrypoint", "/bin/sh", r.ImageID)
		return append(args, r.Command...), nil
	case "exec":
		x := c.Exec
		if x == nil || !hexID.MatchString(x.ContainerID) || len(x.Command) == 0 {
			return nil, fail("provider_refused")
		}
		args := []string{"exec", "-i", "-u", x.User}
		args = appendPairs(args, "-e", x.Env)
		if x.Directory != "" {
			if x.Directory != "/workspace" {
				return nil, fail("provider_refused")
			}
			args = append(args, "-w", x.Directory)
		}
		args = append(args, x.ContainerID)
		return append(args, x.Command...), nil
	case "build":
		b := c.Build
		if b == nil || !filepath.IsAbs(b.Context) || !filepath.IsAbs(b.Dockerfile) || b.Tag == "" || b.Target == "" {
			return nil, fail("provider_refused")
		}
		args := []string{"buildx", "build", "--load", "-f", b.Dockerfile, "-t", b.Tag, "--target", b.Target}
		args = appendPairs(args, "--build-arg", b.Args)
		return append(args, b.Context), nil
	default:
		return nil, fail("provider_refused")
	}
}
